## stg_jira__user

    - name: stg_jira__user
      description: "Cleaned and standardized JIRA user accounts with validated email addresses and consistent naming"
      source_table: "raw.user"
      columns:
        - name: user_id
          data_type: VARCHAR
          constraints: [not_null, unique]
        - name: user_display_name
          data_type: VARCHAR
          constraints: [not_null]
        - name: username
          data_type: VARCHAR
        - name: email
          data_type: VARCHAR
          validation_rules:
            - rule: "email = LOWER(TRIM(email))"
              on_failure: correct
            - rule: "email LIKE '%@%.%' OR email IS NULL"
              on_failure: nullify_field
        - name: locale
          data_type: VARCHAR
        - name: time_zone
          data_type: VARCHAR
        - name: is_active
          data_type: BOOLEAN



## stg_jira__project

    - name: stg_jira__project
      description: "Cleaned JIRA projects with standardized naming and validated project keys"
      source_table: "raw.project"
      columns:
        - name: project_id
          data_type: VARCHAR
          constraints: [not_null, unique]
          validation_rules:
            - rule: "project_id IS NOT NULL AND TRIM(project_id) != ''"
              on_failure: delete_row
        - name: project_key
          data_type: VARCHAR
          constraints: [not_null]
          validation_rules:
            - rule: "project_key = UPPER(TRIM(project_key))"
              on_failure: correct
            - rule: "LENGTH(project_key) BETWEEN 2 AND 10"
              on_failure: delete_row
        - name: project_name
          data_type: VARCHAR
          constraints: [not_null]
          validation_rules:
            - rule: "project_name = TRIM(project_name)"
              on_failure: correct
            - rule: "LENGTH(project_name) > 0"
              on_failure: delete_row
        - name: project_description
