        description: Resolution timestamp from the source issue record.
      - name: updated_at
        data_type: TIMESTAMP
        description: Timestamp of the latest issue update (source value).
      - name: project_id
        data_type: VARCHAR
        description: Project identifier the issue belongs to.
      - name: assignee_user_id
        data_type: VARCHAR
        description: Current assignee user identifier.
      - name: reporter_user_id
